public class Student extends Person {private final String course;public Student(String n,int a,String c){super(n,a);if(c==null||c.isBlank())throw new IllegalArgumentException();course=c.trim();}@Override public String display(){return super.display()+", course: "+course;}public static void main(String[]a){System.out.println(new Student("Tariro",21,"Computer Science").display());}}
